22	{
23		if(!(upCast(_context)->getExcludeFile().empty())){
24			string ex = upCast(_context)->getExcludeFile();
25			_excludeFile = new BedFile(ex);
26			_excludeFile->loadBedFileIntoMergedMap();
27			_haveExclude = true;
28		}
