32	bool Fisher::finalizeCalculations()
33	{
34	    _sweep->closeOut();
35	    _queryUnion = _sweep->getQueryTotalRecordLength();
36	    _dbUnion = _sweep->getDatabaseTotalRecordLength();
37	
38	    _queryCounts = _sweep->getQueryTotalRecords();
39	    _dbCounts = _sweep->getDatabaseTotalRecords();
40	
41	    _unionVal = _queryUnion + _dbUnion;
42	    return true;
43	}
