100	unsigned long Fisher::getTotalIntersection(RecordKeyVector &recList)
101	{
102	    unsigned long intersection = 0;
103	    Record *key = recList.getKey();
104	    CHRPOS keyStart = key->getStartPos();
105	    CHRPOS keyEnd = key->getEndPos();
106	
107	    _overlapCounts += recList.size();
108	    // note that we truncate to a max size of 2.1GB
109	    _qsizes.push_back((int)(keyEnd - keyStart));
110	
111	    int hitIdx = 0;
112	    for (RecordKeyVector::iterator_type iter = recList.begin(); iter != recList.end(); iter = recList.next()) {
113	        CHRPOS maxStart = max((*iter)->getStartPos(), keyStart);
114	        CHRPOS minEnd = min((*iter)->getEndPos(), keyEnd);
115	        _qsizes.push_back((int)(minEnd - maxStart));
116	        if (_context->getObeySplits()) {
117	            intersection += upCast(_context)->getSplitBlockInfo()->getOverlapBases(hitIdx);
118	            hitIdx++;
119	        } else {
120	            intersection += (unsigned long)(minEnd - maxStart);
121	        }
122	    }
123	    _numIntersections += (int)recList.size();
124	    return intersection;
125	}
