381	bool NewChromSweep::queryChromAfterDbRec(const Record *dbRec)
382	{
383	    //If using a genome file, compare chrom ids.
384	    //Otherwise, compare global order, inserting as needed.
385	    if (_context->hasGenomeFile()) {
386	        return (_currQueryRec->getChromId() > dbRec->getChromId()) ;
387	    }
388	    //see if query has both
389	    const string &qChrom = _currQueryRec->getChrName();
390	    const string &dbChrom = dbRec->getChrName();
391	    const _orderTrackType *track = _fileTracks[_currQueryRec->getFileIdx()];
392	    _orderTrackType::const_iterator iter = track->find(qChrom);
393	
394	
395	    int qOrder = iter->second;
396	    iter = track->find(dbChrom);
397	    if (iter == track->end()) {
398	        //query file does not contain the dbChrom.
399	        //try a lexicographical comparison, if possible.
400	        return testLexicoQueryAfterDb(_currQueryRec, dbRec);
401	    }
402	    int dbOrder = iter->second;
403	
404	    return (qOrder > dbOrder);
405	}
