408	int NewChromSweep::findChromOrder(const Record *rec) {
409	    const string &chrom = rec->getChrName();
410	    int fileIdx = rec->getFileIdx();
411	    _orderTrackType *track = _fileTracks[fileIdx];
412	
413	    _orderTrackType::const_iterator iter = track->find(chrom);
414	    if (iter == track->end()) {
415	        //chrom never seen before. Enter into map.
416	        int val = (int)track->size();
417	        track->insert(pair<string, int>(chrom, val));
418	        return val;
419	    } else {
420	        return iter->second;
421	    }
