// Consume whatever is left of the query and database files after the sweep
// itself has finished. This is what makes the running totals maintained by
// nextRecord() (total record counts and total record lengths) describe the
// *entire* input files rather than only the portion the sweep had to visit.
// Tools that report summary statistics over both files (e.g. jaccard, fisher)
// depend on that, since records lying beyond the last query record still
// belong to the sample even though they can never produce an overlap.
//
// The optional testChromOrderVal flag only controls whether the chromosome
// sort order of the drained records is additionally verified; it must never
// decide *whether* the remaining records are accounted for.
void NewChromSweep::closeOut(bool testChromOrderVal) {
    if (_testLastQueryRec) {
        testChromOrder(_currQueryRec);
    }
    bool should_test_last_rec = true;
    while (!_queryFRM->eof()) {
        nextRecord(true);
        testChromOrder(_currQueryRec);
        _queryFRM->deleteRecord(_currQueryRec);
		should_test_last_rec = false;
    }
    if (testChromOrderVal && should_test_last_rec) testChromOrder(_currQueryRec);

    for (int i=0; i < _numDBs; i++) {
        while (!_dbFRMs[i]->eof()) {
            if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
            _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
            nextRecord(false, i);
        }
        if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
    }
}

